import { PrismaClient } from "@prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { Pool } from "pg";
import { createHmac } from "crypto";
import bcrypt from "bcryptjs";
import * as dotenv from "dotenv";

dotenv.config({ path: ".env.local" });

// Strip sslmode from the URL so the ssl option below takes full effect
const dbUrl = (process.env.DATABASE_URL ?? "").replace(/([?&])sslmode=[^&]*/g, "$1").replace(/[?&]$/, "");
const pool = new Pool({
  connectionString: dbUrl,
  ssl: { rejectUnauthorized: false },
});
const adapter = new PrismaPg(pool);
const prisma = new PrismaClient({ adapter });

function hashKey(raw: string): string {
  const secret = process.env.SECRET_KEY_HMAC_SECRET;
  if (!secret) throw new Error("SECRET_KEY_HMAC_SECRET not set");
  return createHmac("sha256", secret).update(raw.trim().toLowerCase()).digest("hex");
}

